TUs will look like this but overly simplified

```c
static void someCallerFunc() {
    someOtherFunc1();
    someOtherFunc2();
    someOtherFunc3();
}

static void someMainFunc() {
    // ...
    someCallerFunc();
    // ...
}
```
which after the compiler generates the .o it will look like
```c
// now this func is never called, thus marked UNUSED
static void someCallerFunc() {
    someOtherFunc1();
    someOtherFunc2();
    someOtherFunc3();
}

static void someMainFunc() {
    // ...
    someOtherFunc1();
    someOtherFunc2();
    someOtherFunc3();
    // ...
}
```

```c

s32 check_common_airborne_cancels(struct MarioState *m) {
    if (m->pos[1] < m->waterLevel - 100) {
        return set_water_plunge_action(m);
    }

    if (m->input & INPUT_SQUISHED) {
        return drop_and_set_mario_action(m, ACT_SQUISHED, 0);
    }

    if (m->floor->type == SURFACE_VERTICAL_WIND && (m->action & ACT_FLAG_ALLOW_VERTICAL_WIND_ACTION)) {
        return drop_and_set_mario_action(m, ACT_VERTICAL_WIND, 0);
    }

    m->quicksandDepth = 0.0f;
    return FALSE;
}```

